			add("book.rusticrevived.entry.wildberries", "野莓果");
			add("book.rusticrevived.entry.grapes", "葡萄");
			add("book.rusticrevived.entry.apple_trees", "苹果树");
			add("book.rusticrevived.entry.olive_trees", "橄榄树");
			add("book.rusticrevived.entry.ironwood_trees", "铁树");
			add("book.rusticrevived.entry.herbs", "草药");
			add("book.rusticrevived.entry.alchemy", "炼金");
